<?php
namespace App\Domains\Evidence\Models; use App\Domains\System\Models\User; use Illuminate\Database\Eloquent\Model;
class SurveyResponse extends Model { protected $fillable=['survey_id','survey_respondent_id','status','started_at','submitted_at','raw_payload','collected_by']; protected $casts=['started_at'=>'datetime','submitted_at'=>'datetime','raw_payload'=>'array']; public function survey(){return $this->belongsTo(Survey::class);} public function respondent(){return $this->belongsTo(SurveyRespondent::class,'survey_respondent_id');} public function answers(){return $this->hasMany(SurveyResponseAnswer::class);} public function simulatedPurchaseEvents(){return $this->hasMany(SimulatedPurchaseEvent::class);} public function collector(){return $this->belongsTo(User::class,'collected_by');} }
